package pl.zagranietyper;import org.junit.jupiter.api.Test;import pl.zagranietyper.repository.FootballSettlementRepository;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class FootballTeamToAdvanceReviewedSnapshotTest {@Test void immutableBoundary(){assertEquals(30,FootballTeamToAdvanceReviewedSnapshot.APPROVED_IDS.size());assertEquals("d2a76a4cff43d004fc9b38442f66d0753cf2397b93a5ef749bcfa3a11f06abec",FootballTeamToAdvanceReviewedSnapshot.EXPECTED_SHA256);}@Test void dryAndFailedGateNeverWrite(){AtomicInteger n=new AtomicInteger();assertNull(FootballTeamToAdvanceCoverageDryRunMain.applyIfRequested(false,gate(true),List.of(),u->{n.incrementAndGet();return ok();}));assertThrows(IllegalStateException.class,()->FootballTeamToAdvanceCoverageDryRunMain.applyIfRequested(true,gate(false),List.of(),u->{n.incrementAndGet();return ok();}));assertEquals(0,n.get());}@Test void passingGateDelegates(){AtomicInteger n=new AtomicInteger();assertEquals(30,FootballTeamToAdvanceCoverageDryRunMain.applyIfRequested(true,gate(true),List.of(),u->{n.incrementAndGet();return ok();}).updatedLegs());assertEquals(1,n.get());}private static FootballTeamToAdvanceReviewedSnapshot.Gate gate(boolean x){return new FootballTeamToAdvanceReviewedSnapshot.Gate(30,13,17,0,"x",19,9,2,0,Set.of(),Set.of(),x,x,x,x);}private static FootballSettlementRepository.ApplyResult ok(){return new FootballSettlementRepository.ApplyResult(30,0,13,17,0,25,10,15,0,0,0);}}
